                             <th>Avg Commute</th>
                             <th>Distance</th>
                             <th>Median Price</th>
                             <th>$/sqft</th>
                         </tr>
                     </thead>
                     <tbody>{rows_html}</tbody>
                 </table>
             </div>
         </details>"""
 
 
