                         bVal = b.cells[1].textContent;
                         break;
                     case 'zip':
                         aVal = a.cells[2].textContent;
                         bVal = b.cells[2].textContent;
                         break;
                     case 'tier':
                         aVal = a.cells[3].textContent.trim();
                         bVal = b.cells[3].textContent.trim();
                         break;
