         .modal {{
             background: white;
             border-radius: 16px;
             padding: 2rem;
             max-width: 700px;
             width: 90%;
             max-height: 85vh;
             overflow-y: auto;
             box-shadow: 0 25px 80px rgba(0,0,0,0.4);
