         'tier_counts': scored_df['Tier'].value_counts().to_dict(),
         'generated':   datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
         'filtered':    len(filtered_df) if filtered_df is not None else 0,
     }
 
     # Build HTML
     html = f"""<!DOCTYPE html>
