                         <td>{row['Avg_Commute_Min']:.1f} min</td>
+                        <td>{f"{row.get('Crime_Score'):.1f}/100" if pd.notna(row.get('Crime_Score')) else "N/A"}</td>
                         <td>{row['Distance_Miles']:.1f} mi</td>
