                         bVal = parseFloat(
                             b.cells[9].textContent.replace(/[$,]/g, '')
                         ) || 0;
                         break;
                 }}
 
                 if (typeof aVal === 'string') {{
                     return ascending
                            ? aVal.localeCompare(bVal)
                            : bVal.localeCompare(aVal);
