             max = max || 100;
             const pct = score / max;
             if (pct >= 0.8) return '#22c55e';
             if (pct >= 0.6) return '#3b82f6';
             if (pct >= 0.4) return '#f59e0b';
             return '#ef4444';
         }}
 
         function trendClass(trend) {{
             if (!trend || trend === 'N/A') return '';
             if (trend === 'increasing') return 'trend-up';
