                                         <span>Commute Score &mdash; ${{d.commute_score}}/100</span>
                                         <span style="font-weight: normal; font-size: 0.9em; text-transform: none; color: #667eea;">
                                             {commute_weight * 100:.0f}% Weight &rarr; <b>+${{(d.commute_score * {commute_weight}).toFixed(1)}} pts</b>
                                         </span>
                                     </div>
                                     <div class="score-row">
                                         <span class="score-label">Commute Score</span>
                                         <span class="score-pill"
                                               style="background:${{scoreColor(d.commute_score)}}">
                                             ${{d.commute_score}}
                                         </span>
                                         <div class="score-bar-wrap">
                                             <div class="score-bar-fill"
                                                  style="width:${{d.commute_score}}%"></div>
                                         </div>
                                     </div>
                                     <div style="font-size: 0.85rem; font-weight: 600; color: #64748b; margin: 1rem 0 0.5rem 0; text-transform: uppercase; letter-spacing: 0.5px;">Work Address 1</div>
                                     <div class="detail-grid">
