                              : 'N/A';
 
             const taxRateStr = d.tax_rate !== null
                 ? d.tax_rate.toFixed(2) + ' per $1k'
                 : 'N/A';
 
             const monthlyTaxStr = d.monthly_tax !== null
                 ? '$' + Math.round(d.monthly_tax).toLocaleString()
