                     </div>
                     <div class="detail-grid">
                         <div class="detail-item">
                             <span class="detail-key">Avg Time</span>
                             <span class="detail-val">
                                 ${{d.avg_commute !== null
                                     ? d.avg_commute.toFixed(1) + ' min' : 'N/A'}}
                             </span>
